return $input.all().map(item => {
  const data = item.json || {};
  const reviewNotes = String(
    data.reviewNotes || data.review_notes || 'Marked as selected via Asset Review API',
  ).trim();
  const reviewNotesSql = reviewNotes.replace(/'/g, "''");

  return {
    json: {
      assetId: data.assetId || data.asset_id || null,
      reviewNotes,
      reviewNotesSql,
      baseUrl: data.baseUrl || data.base_url || 'http://192.168.0.194:9000',
    },
  };
});

const params = $('Normalize Select Params').first().json;
const assetId = params.assetId;
const baseUrl = params.baseUrl || 'http://192.168.0.194:9000';

if (!assetId) {
  return [{
    json: {
      selected: false,
      assetId: null,
      reason: 'assetId is required',
    },
  }];
}

const row = $input.first()?.json ?? {};

if (!row.asset_id || !row.object_path || !row.bucket) {
  return [{
    json: {
      selected: false,
      assetId,
      reason: 'Asset not found, already canonical, or selection failed',
    },
  }];
}

return [{
  json: {
    selected: true,
    assetId: row.asset_id,
    avatar: row.avatar,
    scene: row.scene,
    assetType: row.asset_type,
    url: `${baseUrl}/${row.bucket}/${row.object_path}`,
    bucket: row.bucket,
    objectPath: row.object_path,
    mimeType: row.mime_type,
    status: row.status,
    isCanonical: row.is_canonical,
    canonicalGroup: row.canonical_group,
    sha256: row.sha256,
    reviewNotes: row.review_notes,
    createdAt: row.created_at,
  },
}];
